package cl.uss.ca.external.pure.model;

public class ProjectOrganizationData {
    private String organizationUuid;
    private String organizationSystemName;

    public String getOrganizationUuid() {
        return organizationUuid;
    }

    public void setOrganizationUuid(String organizationUuid) {
        this.organizationUuid = organizationUuid;
    }

    public String getOrganizationSystemName() {
        return organizationSystemName;
    }

    public void setOrganizationSystemName(String organizationSystemName) {
        this.organizationSystemName = organizationSystemName;
    }
}
